from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
import redis

class CeleryQueueHealthCheckView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, queue_name):
        expected_prefix = f"tenant_{request.user.tenant.id}_"
        # Enforce that queue_name strictly belongs to the authenticated user's tenant
        if not queue_name.startswith(expected_prefix):
            return Response({"error": "Queue access forbidden"}, status=status.HTTP_403_FORBIDDEN)

        r = redis.Redis.from_url("redis://localhost:6379/0")
        length = r.llen(queue_name)
        # Expose only queue depth count; never leak task arguments
        return Response({
            "queue": queue_name,
            "backlog_depth": length
        }, status=status.HTTP_200_OK)
